// Permission sheet (R8-final frame 5): who made it, the exact command, read / act / never, network hosts,
// files it reads (v1b-33), the manifest viewer and the equivalent CLI line. Everything shown comes from the core's parsed manifest.
import { useEffect, useRef, useState } from 'react';
import './sheet.css';
import type { ApprovalCore, ApprovalView, Level } from './types';
import { actTarget, type Act } from '../widgets/api'; // v1b-20

interface Props {
  core: ApprovalCore;
  name: string;
  /** v1a-23 r2: an integration source (`~/.nunchiro/sources/<name>`) instead of a widget. */
  subject?: 'widget' | 'source';
  onClose: () => void;
  /** Called with the stored grant after a successful approve. */
  onGranted?: (view: ApprovalView) => void;
}

/** One argv word as a shell would need it, so what is shown is what runs, character for character. */
const word = (w: string) => (/^[\w@%+=:,./-]+$/.test(w) ? w : `'${w.replaceAll("'", `'\\''`)}'`);

export function PermissionSheet({ core, name, subject = 'widget', onClose, onGranted }: Props) {
  const isSource = subject === 'source'; // v1a-23 r2
  const [view, setView] = useState<ApprovalView | null>(null);
  const [error, setError] = useState('');
  const [act, setAct] = useState(false);
  const [source, setSource] = useState(false);
  const [busy, setBusy] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const back = useRef<Element | null>(document.activeElement);

  useEffect(() => {
    core
      .request(isSource ? { op: 'board_source_status', name } : { op: 'approval_status', name })
      .then((r) => setView((r as { view: ApprovalView }).view))
      .catch((e: Error) => setError(e.message));
    const prev = back.current;
    return () => (prev as HTMLElement | null)?.focus?.();
  }, [core, name, isSource]);
  // Focus lands on Cancel, so a stray Enter never approves.
  useEffect(() => {
    root.current?.querySelector<HTMLElement>('[data-cancel]')?.focus();
  }, [view, error]);

  const level: Level = act ? 'act' : 'read';
  const approve = () => {
    if (!view || busy) return;
    setBusy(true);
    core
      .request(isSource ? { op: 'board_source_grant', name, level, hash: view.hash } : { op: 'approval_grant', name, level, hash: view.hash })
      .then((r) => onGranted?.((r as { view: ApprovalView }).view))
      .catch((e: Error) => (setError(e.message), setBusy(false)));
  };
  const keys = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape') return onClose();
    if (e.key !== 'Tab') return;
    const items = [...(root.current?.querySelectorAll<HTMLElement>('button:not(:disabled)') ?? [])];
    const at = items.indexOf(document.activeElement as HTMLElement);
    const next = e.shiftKey ? (at <= 0 ? items.length - 1 : at - 1) : at === items.length - 1 ? 0 : at + 1;
    e.preventDefault();
    items[next]?.focus();
  };

  const m = view?.manifest;
  const canAct = !!m?.permissions.includes('act') && !view?.act_refused;
  // v1b-20: the manifest's `[act]` table, shown verbatim (types.ts predates it).
  const actTable = (m as { act?: Act | null } | undefined)?.act ?? null;
  return (
    <>
      <div className="ps-scrim" onClick={onClose} />
      <div ref={root} className="ps" role="dialog" aria-modal="true" aria-labelledby="ps-title" onKeyDown={keys}>
        <div>
          <h3 id="ps-title">Allow “{name}”?</h3>
          <div className="ps-meta">
            {isSource ? 'Integration source' : 'Custom widget'}
            {m && ` · ${m.kind}`}
            {m && (
              <>
                {' · made by '}
                <span data-field="author">{m.author}</span>
              </>
            )}
            {' · '}
            <span className="mono">
              ~/.nunchiro/{isSource ? 'sources' : 'widgets'}/{name}/
            </span>
            {/* v1a-23 r2: the content this approval is bound to. */}
            {view && (
              <>
                {' · '}
                <span className="mono" data-field="hash">
                  hash {view.hash.slice(0, 12)}
                </span>
              </>
            )}{' '}
            · asked once, and again after any change
          </div>
        </div>
        {error && (
          <p role="alert" className="ps-error">
            {error}
          </p>
        )}
        {view?.state === 'changed' && (
          <p role="status" className="ps-changed">
            Changed since you allowed it. Review it again.
          </p>
        )}
        {view && m && (
          <>
            <div>
              <b>
                {m.kind === 'web'
                  ? 'Page to show'
                  : `Command to run (exactly this${m.interval_secs ? `, every ${m.interval_secs} s` : ', no repeat'})`}
              </b>
              <pre data-field="command">{m.kind === 'web' ? m.entry : m.command.map(word).join(' ')}</pre>
              {m.kind !== 'web' && (
                <p className="ps-meta" data-field="runtime-limit">
                  Commands whose runtime spawns children with <code>posix_spawn</code> fail closed.{' '}
                  {/* v1b-21 r2 (ruling 09:48 Q3): macOS enforces no per-process memory limit. */}
                  Each run stops after 5 s and may start at most 64 processes; memory is limited only by those two.
                </p>
              )}
            </div>
            <div className="ps-perm">
              <div className="ps-row">
                <span className="ps-pk">Read</span>
                <ul>
                  <li>{m.kind === 'web' ? 'Show its page' : 'Show the command’s output (text or JSON) as a table'}</li>
                  <li>Project names and the session list with states</li>
                </ul>
                <span className="ps-tag">default · on</span>
              </div>
              <div className="ps-row">
                <span className="ps-pk">Act</span>
                <ul>
                  {view.act_refused ? (
                    <li className="ps-error" data-field="act-refused" id="ps-act-refused">
                      {view.act_refused}
                    </li>
                  ) : (
                    <li>{canAct ? 'Send text you set to a session, or start a session' : 'Not requested by this widget'}</li>
                  )}
                  {/* v1b-20 */}
                  {actTable && (
                    <li>
                      When you click a row, sends to <b data-field="act-target">{actTarget(actTable)}</b>:
                      <pre data-field="act-template">{actTable.template}</pre>
                    </li>
                  )}
                  <li>Logged as “widget {name}”</li>
                </ul>
                <button
                  className="ps-switch"
                  role="switch"
                  aria-checked={act}
                  aria-label="Allow act"
                  aria-describedby={view.act_refused ? 'ps-act-refused' : undefined}
                  disabled={!canAct}
                  onClick={() => setAct(!act)}
                >
                  <i className={act ? 'on' : ''} /> {act ? 'on' : 'off'}
                </button>
              </div>
              <div className="ps-row ps-never">
                <span className="ps-pk">Never</span>
                <ul>
                  <li>Answer pending decisions</li>
                  <li>Change settings · touch agent config</li>
                </ul>
                <span className="ps-tag">always</span>
              </div>
              <div className="ps-row">
                <span className="ps-pk">Network</span>
                <span data-field="network">
                  {m.network.length ? (
                    <>
                      Hosts it may reach: <span className="mono">{m.network.join(' · ')}</span> · all other hosts blocked
                    </>
                  ) : (
                    'No network · all hosts blocked'
                  )}
                </span>
                <span className="ps-tag">{m.network.length ? 'allowed' : 'none'}</span>
              </div>
              {/* v1b-33 (needs 45): script widgets read their project, cache and tools, plus what they declare. */}
              {m.kind === 'script' && (
                <div className="ps-row">
                  <span className="ps-pk" id="ps-files">
                    Files
                  </span>
                  {/* r2 (review S3, S4): named for screen readers; the default names the user tool folders too. */}
                  <div data-field="read" role="group" aria-labelledby="ps-files">
                    Its project folder, its cache, system tools, ~/.cargo/bin and ~/.local/bin
                    {m.read.length ? (
                      <>
                        {', and also:'}
                        <ul className="mono">
                          {m.read.map((p) => (
                            <li key={p}>{p}</li>
                          ))}
                        </ul>
                      </>
                    ) : (
                      ' · nothing else in your home'
                    )}
                    {view.read_home_wide && (
                      <p className="ps-danger" data-field="read-warning" role="note">
                        Reads your whole home folder: documents, other projects and app data. Agent config and keys stay blocked.
                      </p>
                    )}
                  </div>
                  <span className="ps-tag">{m.read.length ? 'declared' : 'default'}</span>
                </div>
              )}
            </div>
            {source && (
              <pre data-field="manifest" aria-label="widget.toml">
                {view.manifest_text}
              </pre>
            )}
          </>
        )}
        <div className="ps-acts">
          <button className="btn" aria-expanded={source} disabled={!view} onClick={() => setSource(!source)}>
            {source ? 'Hide widget.toml' : 'View widget.toml'}
          </button>
          <span className="dim mono" data-field="cli">
            = {view ? view.cli.replace(/--read$/, `--${level}`) : `nunchiro widget allow ${name} --${level}`}
          </span>
          <span className="sp" />
          <button className="btn" data-cancel onClick={onClose}>
            Cancel
          </button>
          <button className="btn p" disabled={!view || busy} onClick={approve}>
            {act ? 'Allow read and act' : 'Allow read only'}
          </button>
        </div>
      </div>
    </>
  );
}

