// V2-8e (HIDEROWS r6): the decision line under the session row that asked (or under the project header for a
// project-level item), its icon buttons and the compact peek. Keys 1, 2, 3, Space and Enter act only while the session's
// block has focus; they are never printed, the tooltips say them. Risk comes from the core (`isRisky`, fail-closed).
import { useEffect, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';
import type { Answer } from '../queue/answer';
import { answered, DENY_NOTE_MAX, whoOf } from '../queue/answer';
import { kindWord, type Session } from '../types';
import { boardWho } from '../queue/board';
import { isRisky, rowPlan, whatWhy, type Item, type Line } from './decisions';
import { Icon } from '../icons/Icon';

/** Sends one answer for an item; null when this window already sent one for it. */
/** `confirmed`: only the panel card's focus-then-Enter allow of a risky item sets it. */
export type OnAnswer = (d: Item, a: Answer, confirmed?: boolean) => Promise<unknown> | null;

const ICON: Record<'check' | 'info' | 'x' | 'eye', ReactNode> = {
  check: <path d="M4 12.5l5 5L20 6.5" strokeWidth="2.4" />,
  info: (
    <>
      <circle cx="12" cy="12" r="9" />
      <path d="M12 11v5" />
      <path d="M12 7.6h.01" strokeWidth="2.6" />
    </>
  ),
  x: <path d="M6 6l12 12M18 6L6 18" strokeWidth="2.4" />,
  eye: (
    <>
      <path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z" />
      <circle cx="12" cy="12" r="3" />
    </>
  ),
};
const Svg = ({ k }: { k: keyof typeof ICON }) => (
  <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" focusable="false">
    {ICON[k]}
  </svg>
);
function IconButton({ k, tip, cls = '', act, onClick, disabled }: { k: keyof typeof ICON; tip: string; cls?: string; act: string; onClick: () => void; disabled?: boolean }) {
  return (
    <button type="button" className={`qib ${cls}`} data-act={act} data-tip={tip} aria-label={tip} disabled={disabled} onClick={(e) => (e.stopPropagation(), onClick())}>
      <Svg k={k} />
    </button>
  );
}

// One peek at a time across the tree.
let closePeek: (() => void) | null = null;

interface Props {
  line: Line;
  session?: Session;
  /** Under the project header (no session row of its own): the line is its own focus stop and shows the count. */
  head?: boolean;
  onAnswer: OnAnswer;
  /** Jump to the session's panel and its decision card. */
  onDetails: (d: Item) => void;
}

/** A session row and its decision line in one block: number keys, Space and Enter act only while focus is inside it.
 * `row` draws the session row; its click is `details` (the jump to the panel). */
export function DecisionRow(p: Props & { row?: (details: () => void) => ReactNode }) {
  const { node, keys, details } = useDecisionLine(p);
  if (p.head) return <div className="sess hl">{node}</div>;
  return (
    <div className="sess" onKeyDown={keys}>
      {p.row?.(details)}
      {node}
    </div>
  );
}

function useDecisionLine({ line, session, head, onAnswer, onDetails }: Props) {
  const first = line.items[0];
  const plan = rowPlan(line.items, session);
  const risky = line.items.some(isRisky);
  const [denying, setDenying] = useState(false);
  const [peek, setPeek] = useState(false);
  const [, setSent] = useState(0);
  const [err, setErr] = useState<string | null>(null);
  const block = useRef<HTMLDivElement>(null);
  const done = line.answered || line.items.every((d) => answered(d.id));
  // A question that wraps to two lines keeps that height once answered, so answering moves no row (needs 49).
  const held = useRef(0);
  useLayoutEffect(() => {
    if (!done && block.current) held.current = block.current.offsetHeight;
  });
  const send = (a: Answer) => {
    const p = onAnswer(first, a);
    if (!p) return;
    setSent((n) => n + 1);
    setErr(null);
    p.then(
      () => setSent((n) => n + 1),
      (e: Error) => (setErr(e.message), setSent((n) => n + 1)),
    );
  };
  const allow = () => plan.allow && !done && send(plan.allow.answer);
  // Deny opens the one-line instruction when the core takes one; otherwise it denies at once.
  const deny = () => {
    if (!plan.deny || plan.choose.length || done) return;
    if (first.deny_note) setDenying(true);
    else send(plan.deny.answer);
  };
  const details = () => (setPeek(false), onDetails(first));
  const togglePeek = () => setPeek((p) => !p);
  const focusRow = () => block.current?.closest('.sess')?.querySelector<HTMLElement>('.row.wt2, .q[tabindex]')?.focus();

  const keys = (e: KeyboardEvent) => {
    const t = e.target as HTMLElement;
    if (e.nativeEvent.isComposing || e.metaKey || e.ctrlKey || e.altKey || t.closest('input, textarea, .peek, .dn')) return;
    const onRow = t.matches('.row.wt2, .q[tabindex]');
    if (e.code === 'Space' && onRow) return e.preventDefault(), togglePeek();
    if (e.key === 'Enter' && onRow) return e.preventDefault(), details();
    if (e.code === 'Digit1') return e.preventDefault(), allow();
    if (e.code === 'Digit2') return e.preventDefault(), details();
    if (e.code === 'Digit3') return e.preventDefault(), deny();
  };

  const count = line.items.length;
  const { what } = whatWhy(first);
  // Under the header there is no session row naming who asks: the line names it (a board item, its source).
  const who = first.board ? boardWho(first.board) : session ? whoOf(session) : first.session_id.slice(0, 6);
  const node = (
    <>
      <div
        ref={block}
        className={`q${done ? ' answered' : ''}${risky ? ' risky' : ''}`}
        data-line={line.key}
        data-item={first.id}
        data-risky={risky || undefined}
        style={done && held.current ? { minHeight: held.current } : undefined}
        tabIndex={head ? 0 : undefined}
        role={head ? 'group' : undefined}
        aria-label={head ? (done ? `answered: ${who}` : `${who}: ${kindWord[first.kind]}. ${count > 1 ? `${count} waiting` : what}`) : undefined}
        onKeyDown={head ? keys : undefined}
        // A click on the line (not on one of its buttons) is the row's click: details.
        onClick={(e) => !(e.target as Element).closest('button, input, .menu') && details()}
      >
        {head && <span className="who">{who}</span>}
        {head && count > 1 && <span className="two">{count}</span>}
        {risky && !done && <b className="warn">Caution</b>}
        <span className="qt" title={first.text}>
          {line.changed ? '↻ changed · updates when you move away' : done ? '✓ answered' : count > 1 ? `${what} +${count - 1}` : what}
        </span>
        {!done && (
          <span className="ag">
            {plan.allow && <IconButton k="check" cls="al" act="allow" tip="Allow (1)" onClick={allow} />}
            {plan.choose.length > 0 && <Choose acts={plan.choose} onPick={(a) => send(a.answer)} />}
            <IconButton k="info" act="details" tip="Details (2)" onClick={details} />
            {plan.deny && !plan.choose.length && <IconButton k="x" cls="no" act="deny" tip="Deny (3)" onClick={deny} />}
            <IconButton k="eye" cls="eye" act="peek" tip="Peek (Space)" onClick={togglePeek} />
          </span>
        )}
      </div>
      {err && (
        <p className="qerr" role="alert">
          {err}
        </p>
      )}
      {denying && !done && <DenyNote onSend={(text) => (setDenying(false), send(text ? { type: 'deny_with', text } : { type: 'deny' }))} onCancel={() => (setDenying(false), focusRow())} />}
      {peek && !done && (
        <Peek
          anchor={block}
          item={first}
          count={count}
          allow={plan.allow ? allow : undefined}
          deny={plan.deny && !plan.choose.length && !risky && count === 1 ? () => plan.deny && send(plan.deny.answer) : undefined}
          details={details}
          onClose={() => (setPeek(false), focusRow())}
        />
      )}
    </>
  );
  return { node, keys, details };
}

function Choose({ acts, onPick }: { acts: { label: string; answer: Answer }[]; onPick: (a: { answer: Answer }) => void }) {
  const [open, setOpen] = useState(false);
  return (
    <span className="dd">
      <button type="button" className="b y" data-act="choose" aria-expanded={open} aria-haspopup="menu" onClick={(e) => (e.stopPropagation(), setOpen((o) => !o))}>
        choose <Icon name="triangle-down" size={12} />
      </button>
      {open && (
        <span className="menu" role="menu">
          {acts.map((a) => (
            <button key={a.label} type="button" role="menuitem" onClick={(e) => (e.stopPropagation(), setOpen(false), onPick(a))}>
              {a.label}
            </button>
          ))}
        </span>
      )}
    </span>
  );
}

/** The row's deny: an optional one-line instruction; Enter sends, Esc cancels, empty sends a plain deny. */
function DenyNote({ onSend, onCancel }: { onSend: (text: string) => void; onCancel: () => void }) {
  const [text, setText] = useState('');
  const input = useRef<HTMLInputElement>(null);
  useEffect(() => input.current?.focus(), []);
  return (
    <div className="dn">
      <input
        ref={input}
        value={text}
        maxLength={DENY_NOTE_MAX}
        placeholder="Tell it what to do instead (optional)"
        aria-label="Instruction sent with the deny (optional)"
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          e.stopPropagation();
          if (e.nativeEvent.isComposing || e.keyCode === 229) return;
          if (e.key === 'Enter') e.preventDefault(), onSend(text.trim());
          if (e.key === 'Escape') e.preventDefault(), onCancel();
        }}
      />
      <button type="button" className="b y" data-act="deny-send" disabled={!text.trim()} onClick={() => onSend(text.trim())}>
        Send
      </button>
      <button type="button" className="b" data-act="deny-plain" onClick={() => onSend('')}>
        Just deny
      </button>
    </div>
  );
}

/** The compact peek (about 260 px): what, why, and allow and deny when the row may send them; else Open in panel. */
function Peek({ anchor, item, count, allow, deny, details, onClose }: { anchor: React.RefObject<HTMLDivElement | null>; item: Item; count: number; allow?: () => void; deny?: () => void; details: () => void; onClose: () => void }) {
  const box = useRef<HTMLDivElement>(null);
  const [at, setAt] = useState<{ left: number; top: number } | null>(null);
  const { what, why } = whatWhy(item);
  useLayoutEffect(() => {
    const a = anchor.current?.getBoundingClientRect();
    const side = anchor.current?.closest('aside')?.getBoundingClientRect();
    if (a) setAt({ left: (side?.right ?? a.right) + 8, top: Math.max(4, Math.min(a.top - 4, window.innerHeight - 140)) });
  }, [anchor]);
  useEffect(() => {
    closePeek?.();
    closePeek = onClose;
    return () => void (closePeek === onClose && (closePeek = null));
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  // Focus moves to the peek itself once it is placed (a hidden box takes no focus; a focused button would show its
  // tooltip, which takes the first Esc); Esc and Space close it and give focus back, Tab reaches its buttons.
  useEffect(() => void (at && box.current?.focus()), [at]);
  return (
    <div
      ref={box}
      className="peek"
      tabIndex={-1}
      role="dialog"
      aria-label={`Peek: ${what}`}
      style={at ? { left: at.left, top: at.top } : { visibility: 'hidden' }}
      onKeyDown={(e) => {
        if (e.nativeEvent.isComposing) return;
        e.stopPropagation();
        if (e.key === 'Escape' || e.code === 'Space') return e.preventDefault(), onClose();
        if (e.code === 'Digit1' && allow) return e.preventDefault(), allow();
        if (e.code === 'Digit2') return e.preventDefault(), details();
        if (e.code === 'Digit3' && deny) return e.preventDefault(), deny();
      }}
    >
      <code title={item.text}>{count > 1 ? `${what} +${count - 1}` : what}</code>
      <p className="why2">{why}</p>
      <div className="ag">
        {/* No allow here (risky, a choice, several pending): the panel allows it. */}
        {!allow && (
          <button type="button" className="b y" data-act="details" onClick={details}>
            Open in panel
          </button>
        )}
        {allow && <IconButton k="check" cls="al" act="allow" tip="Allow (1)" onClick={allow} />}
        {deny && <IconButton k="x" cls="no" act="deny" tip="Deny (3)" onClick={deny} />}
      </div>
    </div>
  );
}

src/chat/DecisionCard.tsx:
// V2-8e (HIDEROWS r6, amended by DECISIONW): one session's decision card, hosted by the Decisions widget
// (decisions/DecisionsWidget.tsx). 1 allows and 3 deny; a risky permission allows only by focus then Enter (never a
// click or key 1); "don't ask again" is mouse only and only here. Esc returns to the place a jump came from. Several
// items are listed one by one: there is no allow-all. `hosted` drops the breadcrumb and the card's own title (the
// widget header and the group header name the place); the answer, risky and focus logic is the same either way.
import { useEffect, useRef, useState } from 'react';
import { answered, DENY_NOTE_MAX, plan as fullPlan, whoOf, type Answer } from '../queue/answer';
import { asks, isRisky, rowPlan, whatWhy, type Item } from '../tree/decisions';
import type { OnAnswer } from '../tree/DecisionLine';
import type { Session } from '../types';
import './decision-card.css';

interface Props {
  session: Session;
  /** The session the jump came from (the breadcrumb's target); null when there is none to go back to. */
  from?: { id: string; name: string } | null;
  onAnswer: OnAnswer;
  onBack: () => void;
  /** Hosted in the Decisions widget: no breadcrumb, a group header with the age; an answer does not navigate. */
  hosted?: { age: string };
  /** Hosted: a changing number asks this card to take focus (a jump from a decision row). Unhosted, it always does. */
  focusAsk?: number;
  /** Hosted: the ask was used (focus moved once); the host drops it so a later mount or item never takes focus. */
  onFocused?: () => void;
  /** Hosted: an answer was sent (the host ends the jump; nothing navigates). */
  onAnswered?: () => void;
}

export function DecisionCard({ session, from = null, onAnswer, onBack, hosted, focusAsk, onFocused, onAnswered }: Props) {
  const items = asks(session.pending) as Item[];
  const root = useRef<HTMLDivElement>(null);
  const focusFirst = () => {
    const first = root.current?.querySelector<HTMLElement>('.dc-item');
    const pick = (sel: string) => first?.querySelector<HTMLElement>(sel);
    (first?.classList.contains('risky') ? pick('[data-act="deny"]') : (pick('[data-act="allow"]') ?? pick('[data-act="choose"]') ?? pick('[data-act="deny"]')))?.focus();
  };
  const ask = !hosted || focusAsk !== undefined;
  useEffect(() => {
    if (!ask) return;
    // The first item's first safe action takes focus: on a risky one its deny (allow needs a deliberate focus). After
    // the frame, so the move the jump makes (which focuses its pane) comes first.
    const t = setTimeout(() => (focusFirst(), hosted && onFocused?.()), 0);
    return () => clearTimeout(t);
  }, [session.id, focusAsk]); // eslint-disable-line react-hooks/exhaustive-deps
  if (!items.length) return null;
  const name = whoOf(session);
  return (
    <div
      ref={root}
      className={`deccard${hosted ? ' hosted' : ''}`}
      data-session={session.id}
      role="region"
      aria-label={`${name}: ${items.length === 1 ? 'decision' : `${items.length} decisions`}`}
      onKeyDown={(e) => {
        if (e.nativeEvent.isComposing || e.metaKey || e.ctrlKey || e.altKey) return;
        if (e.key === 'Escape') return e.preventDefault(), onBack();
      }}
    >
      {from && (
        <button type="button" className="dc-back" onClick={onBack}>
          ← Back to {from.name} (⌘[)
        </button>
      )}
      {hosted ? (
        <div className="dwh">
          <b>{name}</b>
          <span className="tm">{hosted.age}</span>
        </div>
      ) : (
        <h4>
          {name} · {items.length === 1 ? kindTitle(items[0]) : `${items.length} waiting`}
        </h4>
      )}
      {items.map((d) => (
        <CardItem key={d.id} d={d} session={session} onAnswer={onAnswer} onDone={hosted ? (onAnswered ?? (() => {})) : onBack} />
      ))}
      {items.length > 1 && <p className="dc-hint">One at a time: there is no "allow all".</p>}
    </div>
  );
}

const kindTitle = (d: Item) => (d.kind === 'question' ? 'question' : isRisky(d) ? 'risky permission' : 'permission');

function CardItem({ d, session, onAnswer, onDone }: { d: Item; session: Session; onAnswer: OnAnswer; onDone: () => void }) {
  const plan = rowPlan([d], session);
  const terminal = fullPlan(d, session).terminal;
  const risky = isRisky(d);
  const [note, setNote] = useState('');
  const [err, setErr] = useState<string | null>(null);
  const [hint, setHint] = useState(false);
  const [, setSent] = useState(0);
  const { what, why } = whatWhy(d);
  const done = answered(d.id);
  const send = (a: Answer, confirmed = false) => {
    const p = onAnswer(d, a, confirmed);
    if (!p) return;
    setSent((n) => n + 1);
    p.then(onDone, (e: Error) => (setErr(e.message), setSent((n) => n + 1)));
  };
  const deny = () => plan.deny && send(note.trim() && d.deny_note && d.kind === 'permission' ? { type: 'deny_with', text: note.trim() } : plan.deny.answer);
  // The risky allow is the plain allow once, sent only by Enter on the focused button.
  const allowOnce = risky && d.kind === 'permission' && !plan.note ? ({ type: 'allow_once' } as Answer) : plan.allow?.answer;
  return (
    <div
      className={`dc-item${risky ? ' risky' : ''}`}
      data-item={d.id}
      onKeyDown={(e) => {
        const t = e.target as HTMLElement;
        if (e.nativeEvent.isComposing || e.metaKey || e.ctrlKey || e.altKey || t.closest('input')) return;
        if (e.code === 'Digit1' && plan.allow) return e.preventDefault(), send(plan.allow.answer);
        if (e.code === 'Digit3' && plan.deny && d.kind !== 'question') return e.preventDefault(), deny();
        const n = /^Digit([1-9])$/.exec(e.code);
        const pick = n && d.kind === 'question' ? plan.choose[Number(n[1]) - 1] : undefined;
        if (pick) return e.preventDefault(), send(pick.answer);
      }}
    >
      <p className="dc-what">
        {risky && <b className="warn">Caution</b>}
        <b>What</b> {what}
      </p>
      <p className="dc-why">
        <b>Why</b> {why}
      </p>
      {/* The whole request, scrollable: a focus stop so a keyboard can scroll it. */}
      {d.text !== what && (
        <code className="dc-code" tabIndex={0} aria-label="Full request">
          {d.text}
        </code>
      )}
      {plan.note ? (
        <p className="dc-hint">{plan.note}</p>
      ) : (
        <div className="dc-btns">
          {d.kind === 'question' &&
            plan.choose.map((a, i) => (
              <button key={a.label} type="button" className={`b${i ? '' : ' y'}`} data-act="choose" disabled={done} onClick={() => send(a.answer)}>
                {a.label}
              </button>
            ))}
          {d.kind !== 'question' && allowOnce && !risky && (
            <button type="button" className="b y" data-act="allow" disabled={done} title="Allow (1)" onClick={() => send(allowOnce)}>
              Allow
            </button>
          )}
          {/* A risky card leads with deny (mockup r6); its allow follows, by focus then Enter. */}
          {plan.deny && risky && (
            <button type="button" className="b d" data-act="deny" disabled={done} title={d.kind === 'question' ? 'Cancel' : 'Deny (3)'} onClick={deny}>
              {d.kind === 'question' ? 'Cancel' : 'Deny'}
            </button>
          )}
          {d.kind !== 'question' && allowOnce && risky && (
            <button
              type="button"
              className="b r risky"
              data-act="allow"
              disabled={done}
              title="Allow: focus this button, then press Enter"
              onKeyDown={(e) => {
                if (e.key !== 'Enter' || e.nativeEvent.isComposing) return;
                e.preventDefault();
                e.stopPropagation();
                // The one confirmed allow: the core refuses an unconfirmed allow of a risky item.
                send(allowOnce, true);
              }}
              // A click (mouse, touch or Space) never allows a risky request: it focuses and says how.
              onClick={(e) => (e.preventDefault(), e.currentTarget.focus(), setHint(true))}
            >
              Allow (focus, then Enter)
            </button>
          )}
          {plan.deny && !risky && (
            <button type="button" className="b d" data-act="deny" disabled={done} title={d.kind === 'question' ? 'Cancel' : 'Deny (3)'} onClick={deny}>
              {d.kind === 'question' ? 'Cancel' : 'Deny'}
            </button>
          )}
          {d.allow_always && !risky && (
            <button
              type="button"
              className="b"
              data-act="allow-always"
              tabIndex={-1}
              disabled={done}
              title={`Mouse only · the agent's option: ${d.allow_always}`}
              // Mouse only: a keyboard press (detail 0) does nothing.
              onClick={(e) => e.detail > 0 && send({ type: 'allow_always' })}
            >
              Don't ask again this session
            </button>
          )}
        </div>
      )}
      {/* Options that persist to the agent's config are never sent from the window (v1a-03): text only. */}
      {terminal.length > 0 && (
        <p className="dc-hint" title={terminal.join('\n')}>
          {terminal.join(' · ')} · answer in the terminal
        </p>
      )}
      {plan.deny && d.deny_note && d.kind === 'permission' && !plan.note && (
        <input
          className="dc-note"
          value={note}
          maxLength={DENY_NOTE_MAX}
          disabled={done}
          placeholder="Tell it what to do instead (optional, sent with the deny)"
          aria-label="Instruction sent with the deny (optional)"
          onChange={(e) => setNote(e.target.value)}
          onKeyDown={(e) => {
            if (e.nativeEvent.isComposing || e.keyCode === 229) return;
            if (e.key === 'Enter') e.preventDefault(), deny();
          }}
        />
      )}
      {hint && <p className="dc-hint">A click does not allow a risky request: keep focus on the button and press Enter.</p>}
      {err && (
        <p className="dc-hint err" role="alert">
          {err}
        </p>
      )}
    </div>
  );
}

